import{_ as n,a0 as r,w as s,s as u,ao as p,I as a,x as i,a1 as o,A as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse(`{"title":"10個關於linux中Squid代理服務器的實用面試問答 | LCTT x X-CMD","titleTemplate":false,"description":"10個關於linux中Squid代理服務器的實用面試問答 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10個關於linux中Squid代理服務器的實用面試問答 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10個關於linux中Squid代理服務器的實用面試問答 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140729 10 Useful 'Squid Proxy Server' Interview Questions and Answers in Linux","title":"10個關於linux中Squid代理服務器的實用面試問答","tag":"201409","desc":""},"relativePath":"201409/20140729 10 Useful 'Squid Proxy Server' Interview Questions and Answers in Linux.md","filePath":"[post].md"}`),l={name:"201409/20140729 10 Useful 'Squid Proxy Server' Interview Questions and Answers in Linux.md"};function q(c,e,S,b,h,m){const t=r("Link");return s(),u("div",null,[e[13]||(e[13]=p(`<h1 id="_10個關於linux中squid代理服務器的實用面試問答" tabindex="-1">10個關於linux中Squid代理服務器的實用面試問答 <a class="header-anchor" href="#_10個關於linux中squid代理服務器的實用面試問答" aria-label="Permalink to “10個關於linux中Squid代理服務器的實用面試問答”">​</a></h1><p>不僅是系統管理員和網絡管理員時不時會聽到“代理服務器”這個詞，我們也經常聽到。代理服務器已經成為一種企業常態，而且經常會接觸到它。它現在也出現在一些小型的學校或者大型跨國公司的自助餐廳裏。Squid（常被視作代理服務的代名詞）就是這樣一個應用程序，它不但可以被作為代理服務器，其同時也是在該類工具中比較被廣泛使用的一種。</p><p>本文旨在提高你在遇到關於代理服務器面試點時的一些基本應對能力。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Squid-Interview-Questions.png" alt="Squid Interview Questions"></p><p>以下為面試問答的內容</p><h3 id="_1-什麼是代理服務器-代理服務器在計算機網絡中有什麼用途" tabindex="-1">1. 什麼是代理服務器？代理服務器在計算機網絡中有什麼用途？ <a class="header-anchor" href="#_1-什麼是代理服務器-代理服務器在計算機網絡中有什麼用途" aria-label="Permalink to “1. 什麼是代理服務器？代理服務器在計算機網絡中有什麼用途？”">​</a></h3><blockquote><p><strong>回答</strong> : 代理服務器是指那些作為客户端和資源提供商或服務器之間的中間件的物理機或者應用程序。客户端從代理服務器中尋找文件、頁面或者是數據，而且代理服務器能處理客户端與服務器之間所有複雜事務，從而滿足客户端的生成的需求。</p></blockquote><p>代理服務器是WWW（萬維網）的支柱，它們其中大部分都是Web代理。一台代理服務器能處理客户端與服務器之間的複雜通信事務。此外，它在網絡上提供的是匿名信息（LCTT 譯註：指瀏覽者的 IP、瀏覽器信息等被隱藏），這就意味着你的身份和瀏覽痕跡都是安全的。代理可以去配置允許哪些網站的客户能看到，哪些網站被屏蔽了。</p><h3 id="_2-squid是什麼" tabindex="-1">2. Squid是什麼? <a class="header-anchor" href="#_2-squid是什麼" aria-label="Permalink to “2. Squid是什麼?”">​</a></h3><blockquote><p><strong>回答</strong> : Squid是一個在GNU/GPL協議下發布的既可作為代理服務器，同時也可作為Web緩存守護進程的應用軟件。Squid主要是支持像HTTP和FTP那樣的協議，但是對其它的協議比如HTTPS，SSL,TLS等同樣也能支持。其特點是Web緩存守護進程通過從經常上訪問的網站裏緩存Web和DNS數據，從而讓上網速度更快。Squid支持所有的主流平台，包括Linux，UNIX，微軟公司的Windows和蘋果公司的Mac。</p></blockquote><h3 id="_3-squid的默認端口是什麼-怎麼去修改它的操作端口" tabindex="-1">3. Squid的默認端口是什麼？怎麼去修改它的操作端口？ <a class="header-anchor" href="#_3-squid的默認端口是什麼-怎麼去修改它的操作端口" aria-label="Permalink to “3. Squid的默認端口是什麼？怎麼去修改它的操作端口？”">​</a></h3><blockquote><p><strong>回答</strong> : Squid運行時的默認端口是3128。我們可以通過編輯它的配置文件來把它的默認端口修改成未被用户使用的端口，路徑是 /etc/squid/squid.conf ，建議如下。</p></blockquote><p>用你的編輯器打開 ‘/etc/squid/squid.conf’ 文件。</p><pre><code># nano /etc/squid/squid.conf
</code></pre><p>現在把它修改成未被使用的其它端口，並保存退出。</p><pre><code>http_port 3128
</code></pre><p>重新啓動Squid代理服務，如下顯示。</p><pre><code># service squid restart
</code></pre><h3 id="_4-你的公司管理層要求你通過squid代理服務器屏蔽掉一些域名-你怎麼做" tabindex="-1">4. 你的公司管理層要求你通過Squid代理服務器屏蔽掉一些域名，你怎麼做？ <a class="header-anchor" href="#_4-你的公司管理層要求你通過squid代理服務器屏蔽掉一些域名-你怎麼做" aria-label="Permalink to “4. 你的公司管理層要求你通過Squid代理服務器屏蔽掉一些域名，你怎麼做？”">​</a></h3><blockquote><p><strong>回答</strong> : 屏蔽域名是一個在配置文件中實現的功能模組。我們只需要執行一個小的手動配置即可，建議如下。</p></blockquote><p>a. 在 ‘/etc/squid’ 目錄下創建一個名為 ‘blacklist’ 的文件。</p><pre><code># touch /etc/squid/blacklist
</code></pre><p>b. 用nano編輯器打開這個文件。</p><pre><code> # nano /etc/squid/blacklist
</code></pre><p>c. 以每行一個域名的方式將想要屏蔽的域名寫進這個文件裏。</p><pre><code>.facebook.com
.twitter.com
.gmail.com
.yahoo.com
...
</code></pre><p>d. 保存退出，然後從 ‘/etc/squid/squid.conf’ 打開Squid配置文件。</p><pre><code># nano /etc/squid/squid.conf
</code></pre><p>e. 在配置文件中添加如下行。</p><pre><code>acl BLACKLIST dstdom_regex -i “/etc/squid/blacklist”
http_access deny blacklist
</code></pre><p>f. 保存配置文件並退出，重啓Squid服務讓其生效。</p><pre><code># service squid restart
</code></pre><h3 id="_5-在squid中什麼是媒體範圍限制-media-range-limitation-和部分下載" tabindex="-1">5. 在Squid中什麼是媒體範圍限制（Media Range Limitation）和部分下載？ <a class="header-anchor" href="#_5-在squid中什麼是媒體範圍限制-media-range-limitation-和部分下載" aria-label="Permalink to “5. 在Squid中什麼是媒體範圍限制（Media Range Limitation）和部分下載？”">​</a></h3><blockquote><p><strong>回答</strong> : 媒體範圍限制是Squid的一種特殊的功能，它只從服務器中獲取所需要的數據而不是整個文件。這個功能很好的實現了用户在各種視頻流媒體網站如YouTube和Metacafe看視頻時，可以點擊視頻中的進度條來選擇進度，因此整個視頻不用全部都加載，除了一些需要的部分。</p></blockquote><p>Squid部分下載功能的特點是很好地實現了類似在Windows更新時能以一個個小數據包的形式下載，並可以暫停，正因為它的這個特點，正在下載文件的Windows機器可以重新繼續下載，而不用擔心數據會丟失。Squid的媒體範圍限制和部分下載功能只有在存儲了一個完整文件的副本之後才行。此外，當用户訪問另一個頁面時，除非Squid進行了特定的配置，部分下載下來的文件會被刪除且不留在緩存中。</p><h3 id="_6-什麼是squid的反向代理" tabindex="-1">6. 什麼是Squid的反向代理？ <a class="header-anchor" href="#_6-什麼是squid的反向代理" aria-label="Permalink to “6. 什麼是Squid的反向代理？”">​</a></h3><blockquote><p><strong>回答</strong> : 反向代理是Squid的一個功能，這個功能被用來加快最終用户的上網速度。下面用縮寫 ‘RS’ 的表示包含了資源的原服務器，而代理服務器則稱作 ‘PS’ 。初次訪問時，它會從RS得到其提供的數據，並將其副本按照配置好的時間存儲在PS上。這樣的話每次從PS上請求的數據就相當於就是從原服務器上獲取的。這樣就會減輕網絡擁堵，減少CPU使用率，降低網絡資源的利用率，從而緩解原來實際服務器的負載壓力。但是RS統計不了總流量的數據，因為PS分擔了部分原服務器的任務。‘X-Forwarded-For HTTP’ 信息能用於記錄下通過HTTP代理或負載均衡方式連接到RS的客户端最原始的IP地址。</p></blockquote><p>從技術上説，用單個Squid服務器同時作為正向代理服務器和反向代理服務器是可行的。</p><h3 id="_7-由於squid能作為一個web緩存守護進程-那緩存可以刪除嗎-怎麼刪除" tabindex="-1">7. 由於Squid能作為一個Web緩存守護進程，那緩存可以刪除嗎？怎麼刪除？ <a class="header-anchor" href="#_7-由於squid能作為一個web緩存守護進程-那緩存可以刪除嗎-怎麼刪除" aria-label="Permalink to “7. 由於Squid能作為一個Web緩存守護進程，那緩存可以刪除嗎？怎麼刪除？”">​</a></h3><blockquote><p><strong>回答</strong> : 當然！作為一個Web緩存守護進程，Squid能加快網頁的訪問速度，清除緩存也是非常簡單的。</p></blockquote><p>a. 首先停止Squid代理服務，然後從這個 ‘/var/lib/squid/cache’ 目錄中刪除緩存。</p><pre><code># service squid stop
# rm -rf /var/lib/squid/cache/*&lt;
</code></pre><p>b. 創建交換分區目錄。</p><pre><code># squid -z
</code></pre><h3 id="_8-你有一台工作中的機器可以訪問代理服務器-如果想要限制你的孩子的訪問時間-你會怎麼去設置那個場景" tabindex="-1">8. 你有一台工作中的機器可以訪問代理服務器，如果想要限制你的孩子的訪問時間，你會怎麼去設置那個場景？ <a class="header-anchor" href="#_8-你有一台工作中的機器可以訪問代理服務器-如果想要限制你的孩子的訪問時間-你會怎麼去設置那個場景" aria-label="Permalink to “8. 你有一台工作中的機器可以訪問代理服務器，如果想要限制你的孩子的訪問時間，你會怎麼去設置那個場景？”">​</a></h3><p>把允許訪問的時間設置成晚上4點到7點三個小時，跨度為星期一到星期五。</p><p>a. 想要限制Web訪問時間在星期一到星期五的晚上4點到7點，要先打開Squid的配置文件。</p><pre><code># nano /etc/squid/squid.conf
</code></pre><p>b. 在配置文件中添加如下行，保存文件並退出。</p><pre><code>acl ALLOW_TIME time M T W H F 16:00-19:00
shttp_access allow ALLOW_TIME
</code></pre><p>c. 重啓Squid服務。</p><pre><code># service squid restart
</code></pre><h3 id="_9-squid存儲的數據是什麼文件格式" tabindex="-1">9. Squid存儲的數據是什麼文件格式？ <a class="header-anchor" href="#_9-squid存儲的數據是什麼文件格式" aria-label="Permalink to “9. Squid存儲的數據是什麼文件格式？”">​</a></h3><blockquote><p><strong>回答</strong> : Squid存儲的數據是UFS文件格式的。UFS是一種老的，使用比較廣泛的Squid存儲格式</p></blockquote><h3 id="_10-squid的緩存會存儲到哪裏" tabindex="-1">10. Squid的緩存會存儲到哪裏？ <a class="header-anchor" href="#_10-squid的緩存會存儲到哪裏" aria-label="Permalink to “10. Squid的緩存會存儲到哪裏？”">​</a></h3><blockquote><p><strong>回答</strong> : Squid存儲的緩存是位於 ‘/var/spool/squid’ 的特定目錄下。</p></blockquote><p>以上就是全部內容了，很快我還會帶着其它有趣的內容回到這裏。</p><hr>`,58)),a("p",null,[e[1]||(e[1]=i("via: ",-1)),o(t,{href:"http://www.tecmint.com/squid-interview-questions/"},{default:d(()=>[...e[0]||(e[0]=[i("http://www.tecmint.com/squid-interview-questions/",-1)])]),_:1})]),a("p",null,[e[5]||(e[5]=i("作者：",-1)),o(t,{href:"http://www.tecmint.com/author/avishek/"},{default:d(()=>[...e[2]||(e[2]=[i("Avishek Kumar",-1)])]),_:1}),e[6]||(e[6]=i(" 譯者：",-1)),o(t,{href:"https://github.com/ZTinoZ"},{default:d(()=>[...e[3]||(e[3]=[i("ZTinoZ",-1)])]),_:1}),e[7]||(e[7]=i(" 校對：",-1)),o(t,{href:"https://github.com/wxy"},{default:d(()=>[...e[4]||(e[4]=[i("wxy",-1)])]),_:1})]),a("p",null,[e[10]||(e[10]=i("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[8]||(e[8]=[i("LCTT",-1)])]),_:1}),e[11]||(e[11]=i(" 原創翻譯，",-1)),o(t,{href:"http://linux.cn/"},{default:d(()=>[...e[9]||(e[9]=[i("Linux中國",-1)])]),_:1}),e[12]||(e[12]=i(" 榮譽推出",-1))])])}const T=n(l,[["render",q]]);export{x as __pageData,T as default};
